const menu=[{id:'marg',name:'Margherita',price:49,group:'classicas',veg:true,tag:'A essencial',desc:'Molho de tomate, muçarela, manjericão fresco e um fio de azeite.',hue:0},{id:'pepp',name:'Pepperoni',price:59,group:'classicas',veg:false,tag:'A intensa',desc:'Muçarela, pepperoni e molho de tomate. Um clássico com personalidade.',hue:-12},{id:'brasa',name:'Brasa da casa',price:69,group:'autorais',veg:false,tag:'Receita da casa',desc:'Muçarela, linguiça artesanal, cebola roxa e toque de alecrim.',hue:12},{id:'verde',name:'Verde viva',price:55,group:'autorais',veg:true,tag:'Sem carne',desc:'Muçarela, abobrinha, tomate-cereja e folhas de manjericão.',hue:25},{id:'queijos',name:'Quatro queijos',price:62,group:'classicas',veg:true,tag:'A cremosa',desc:'Muçarela, parmesão, provolone e gorgonzola em uma combinação marcante.',hue:8},{id:'mel',name:'Queijo & mel',price:65,group:'autorais',veg:true,tag:'Encontro de sabores',desc:'Muçarela, queijo de cabra, mel e um toque de pimenta-do-reino.',hue:18}];const cart=new Map();const money=v=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(v);const grid=document.getElementById('menu-grid');menu.forEach(p=>{const card=document.createElement('article');card.className='menu-card';card.dataset.category=p.group;card.dataset.veg=String(p.veg);card.innerHTML=`<div class="menu-img"><img src="../assets/pizza.svg" alt="Ilustração conceitual de pizza, não representa a receita específica" loading="lazy" style="filter:hue-rotate(${p.hue}deg)"><span class="pill">${p.tag}</span></div><h3>${p.name}</h3><p>${p.desc}</p><p class="allergen">Contém trigo e leite${p.veg?' · Sem carne':''}</p><div class="menu-card-bottom"><strong>${money(p.price)}</strong><button class="add" aria-label="Adicionar ${p.name}">Adicionar +</button></div>`;card.querySelector('button').addEventListener('click',()=>{cart.set(p.id,(cart.get(p.id)||0)+1);updateCart();document.getElementById('toast').textContent=p.name+' adicionada ao pedido demonstrativo.';clearTimeout(toastTimer);toastTimer=setTimeout(()=>document.getElementById('toast').textContent='',3000)});grid.append(card)});let toastTimer;document.querySelectorAll('[data-menu]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-menu]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('.menu-card').forEach(x=>x.hidden=b.dataset.menu==='vegetarianas'?x.dataset.veg!=='true':b.dataset.menu!=='all'&&x.dataset.category!==b.dataset.menu)}));function updateCart(){document.getElementById('cart-count').textContent=[...cart.values()].reduce((a,b)=>a+b,0);const items=document.getElementById('cart-items');items.replaceChildren();let total=0;if(!cart.size){const p=document.createElement('p');p.textContent='Seu pedido ainda está vazio. Explore o cardápio e adicione um sabor.';items.append(p)}cart.forEach((qty,id)=>{const p=menu.find(x=>x.id===id);total+=p.price*qty;const row=document.createElement('div');row.className='cart-line';row.innerHTML=`<div><h3>${p.name}</h3><small>${money(p.price)} cada</small></div><div class="qty"><button aria-label="Remover uma ${p.name}">−</button><span>${qty}</span><button aria-label="Adicionar uma ${p.name}">+</button></div>`;row.querySelectorAll('button').forEach((b,i)=>b.addEventListener('click',()=>{const next=qty+(i?1:-1);if(next<=0)cart.delete(id);else cart.set(id,next);updateCart();const focus=document.querySelector('#cart-items button')||document.querySelector('#cart-dialog [data-close]');focus.focus()}));items.append(row)});document.getElementById('cart-total').textContent=money(total);document.getElementById('checkout').disabled=!cart.size;document.getElementById('checkout-status').textContent=''}document.getElementById('checkout').addEventListener('click',()=>{document.getElementById('checkout-status').textContent='Pedido demonstrativo conferido! Nenhum pedido foi enviado e nenhum valor será cobrado.'});updateCart();

function syncDock(){document.getElementById('dock-count').textContent=document.getElementById('cart-count').textContent;document.getElementById('dock-total').textContent=document.getElementById('cart-total').textContent}const dockObserver=new MutationObserver(syncDock);dockObserver.observe(document.getElementById('cart-count'),{childList:true,subtree:true,characterData:true});dockObserver.observe(document.getElementById('cart-total'),{childList:true,subtree:true,characterData:true});syncDock();
